"""Compile portable rendering and JSON unit tests, without emulating ESP32 boards or UDP."""

import os
from pathlib import Path
import subprocess
import tempfile

from run_cinema_tests import find_compiler


# AI: below section was generated by an AI
def main():
    """Use temporary build products and the repository's existing compiler discovery."""
    root = Path(__file__).resolve().parent.parent
    compiler, environment = find_compiler()
    msvc = Path(compiler).stem.lower() == "cl"
    # Keep compiler intermediates in the ignored workspace build directory, also in sandboxes.
    build_parent = root / ".pio"
    build_parent.mkdir(exist_ok=True)
    with tempfile.TemporaryDirectory(prefix="ledwall-host-", dir=build_parent) as directory:
        temporary = Path(directory)
        production = root / "usermods/ledwall"
        (temporary / "example-7m-3m.json").write_bytes((production / "example-7m-3m.json").read_bytes())
        remote = (production / "remote_network.cpp").read_text(encoding="utf-8")
        decoder = remote[remote.index("static bool decodeRemote("):remote.index("// HTTP queries cannot target")]
        (temporary / "ledwall_remote_decoder_under_test.h").write_text(decoder, encoding="utf-8")
        cases = {
            "spatial": [root / "tools/ledwall_test.cpp", production / "spatial_model.cpp", production / "spatial_json.cpp"],
            "remote": [root / "tools/ledwall_remote_test.cpp", production / "remote_model.cpp"],
        }
        for name, sources in cases.items():
            executable = temporary / (name + (".exe" if os.name == "nt" else ""))
            if msvc:
                flags = ["/nologo", "/EHsc", "/std:c++17", "/O2", f"/I{temporary}", f"/I{production}", f"/Fe:{executable}"]
            else:
                flags = ["-std=c++17", "-O2", "-Wall", "-Wextra", f"-I{temporary}", f"-I{production}", "-o", str(executable)]
            subprocess.run([compiler, *flags, *map(str, sources)], cwd=temporary, env=environment, check=True)
            subprocess.run([str(executable)], cwd=temporary, env=environment, check=True)


if __name__ == "__main__":
    main()
# AI: end
